    :root {
      --bg: #fff7f1;
      --pink: #ffe2ea;
      --pink2: #f4b7b8;
      --rose: #d77f7d;
      --lav: #e9d5ff;
      --cream: #fff1d7;
      --yellow: #fff1b6;
      --text: #5b4b4f;
      --muted: #8a7880;
      --soft: rgba(255,255,255,.56);
      --line: rgba(255,255,255,.72);
      --shadow: 0 22px 70px rgba(142, 98, 123, .16);
    }
    * { box-sizing: border-box; }
    html, body {
      margin: 0;
      min-height: 100%;
      background: #f4e9fb;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", sans-serif;
      color: var(--text);
      -webkit-font-smoothing: antialiased;
    }
    body {
      min-height: 100vh;
      display: flex;
      justify-content: center;
      overflow-x: hidden;
    }
    button { font: inherit; -webkit-tap-highlight-color: transparent; }
    .phone {
      position: relative;
      width: min(100vw, 430px);
      min-height: 100vh;
      overflow: hidden;
      background:
        radial-gradient(circle at 18% 8%, rgba(255,226,234,.86), transparent 28%),
        radial-gradient(circle at 88% 15%, rgba(233,213,255,.75), transparent 32%),
        radial-gradient(circle at 55% 88%, rgba(255,241,182,.55), transparent 34%),
        linear-gradient(180deg, #fff8f1 0%, #fff4f8 54%, #f4efff 100%);
      padding: 22px 16px 28px;
    }

    .phone.page-1 {
      background:
        radial-gradient(circle at 16% 8%, rgba(255,226,220,.86), transparent 30%),
        radial-gradient(circle at 86% 14%, rgba(255,241,182,.58), transparent 34%),
        radial-gradient(circle at 52% 90%, rgba(255,225,232,.48), transparent 36%),
        linear-gradient(180deg, #fff8f1 0%, #fff1f4 58%, #fff7ed 100%);
    }
    .phone.page-2 {
      background:
        radial-gradient(circle at 14% 12%, rgba(255,196,203,.72), transparent 28%),
        radial-gradient(circle at 88% 20%, rgba(255,204,188,.44), transparent 34%),
        radial-gradient(circle at 50% 88%, rgba(255,243,205,.46), transparent 36%),
        linear-gradient(180deg, #fff6f2 0%, #fff0f5 55%, #fff8ee 100%);
    }
    .phone.page-3 {
      background:
        radial-gradient(circle at 18% 8%, rgba(255,255,255,.88), transparent 30%),
        radial-gradient(circle at 86% 18%, rgba(218,206,244,.56), transparent 35%),
        radial-gradient(circle at 54% 88%, rgba(236,229,255,.48), transparent 38%),
        linear-gradient(180deg, #fffaf4 0%, #f8f4ff 58%, #fff7fb 100%);
    }
    .phone.page-4 {
      background:
        radial-gradient(circle at 14% 10%, rgba(255,229,206,.76), transparent 30%),
        radial-gradient(circle at 86% 22%, rgba(255,203,171,.38), transparent 34%),
        radial-gradient(circle at 52% 86%, rgba(255,241,182,.46), transparent 36%),
        linear-gradient(180deg, #fff9ef 0%, #fff1eb 56%, #fff7f2 100%);
    }
    .phone.page-2 .card { box-shadow: 0 22px 70px rgba(210,116,116,.14); }
    .phone.page-3 .card { box-shadow: 0 22px 70px rgba(128,107,169,.14); }
    .phone.page-4 .card { box-shadow: 0 22px 70px rgba(214,137,85,.15); }
    .phone.page-2 .step-dot.active { background: linear-gradient(90deg, #ef9a9a, #ffd1b8); }
    .phone.page-3 .step-dot.active { background: linear-gradient(90deg, #b9a7e8, #fff1f8); }
    .phone.page-4 .step-dot.active { background: linear-gradient(90deg, #eaa36d, #ffd8a8); }

    .phone::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        radial-gradient(circle at 7% 17%, rgba(255,255,255,.85) 0 1.2px, transparent 1.4px),
        radial-gradient(circle at 83% 21%, rgba(255,255,255,.7) 0 1.1px, transparent 1.3px),
        radial-gradient(circle at 69% 45%, rgba(255,255,255,.65) 0 1px, transparent 1.2px),
        radial-gradient(circle at 24% 67%, rgba(255,255,255,.5) 0 1px, transparent 1.2px);
      pointer-events: none;
    }
    .blob {
      position: absolute;
      border-radius: 999px;
      filter: blur(32px);
      opacity: .7;
      pointer-events: none;
      animation: breathe 6s ease-in-out infinite;
    }
    .blob.one { width: 190px; height: 190px; left: -80px; top: 80px; background: rgba(255,196,203,.43); }
    .blob.two { width: 230px; height: 230px; right: -120px; top: 180px; background: rgba(216,180,254,.35); animation-delay: .9s; }
    .blob.three { width: 210px; height: 210px; left: 110px; bottom: -100px; background: rgba(255,241,182,.35); animation-delay: 1.4s; }
    @keyframes breathe {
      0%, 100% { transform: scale(1); opacity: .62; }
      50% { transform: scale(1.08); opacity: .82; }
    }
    .topbar {
      position: relative;
      z-index: 3;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin-bottom: 12px;
    }
    .pill {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 7px 10px;
      border-radius: 999px;
      background: rgba(255,255,255,.47);
      border: 1px solid rgba(255,255,255,.65);
      backdrop-filter: blur(14px);
      color: #7c6973;
      font-size: 11px;
      line-height: 1;
      white-space: nowrap;
    }
    .dot {
      width: 7px;
      height: 7px;
      border-radius: 999px;
      background: #d98f91;
      box-shadow: 0 0 0 4px rgba(217,143,145,.13);
    }
    .steps { display: flex; gap: 6px; }
    .step-dot {
      width: 6px;
      height: 6px;
      border-radius: 999px;
      background: rgba(255,255,255,.78);
      border: 1px solid rgba(255,255,255,.8);
      transition: all .25s ease;
    }
    .step-dot.active {
      width: 22px;
      background: linear-gradient(90deg, #e69a99, #eac7ff);
      border-color: rgba(255,255,255,.9);
    }
    .card {
      position: relative;
      z-index: 2;
      overflow: hidden;
      min-height: calc(100vh - 86px);
      border-radius: 30px;
      background: rgba(255,255,255,.42);
      border: 1px solid rgba(255,255,255,.68);
      box-shadow: var(--shadow);
      backdrop-filter: blur(22px);
      padding: 14px;
      animation: fadeUp .34s cubic-bezier(.2,.8,.2,1) both;
    }
    .card::before {
      content: "";
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at top, rgba(255,255,255,.65), transparent 58%);
      pointer-events: none;
    }
    .page { position: relative; z-index: 2; display: none; }
    .page.active { display: block; }
    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .hero-img {
      position: relative;
      height: 246px;
      border-radius: 25px;
      overflow: hidden;
      border: 1px solid rgba(255,255,255,.72);
      box-shadow: 0 18px 46px rgba(129, 78, 105, .16);
      background-image: url("data:image/png;base64,");
      background-size: cover;
      background-position: 26% center;
    }
    .hero-img::after {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(180deg, rgba(255,255,255,.06) 0%, rgba(255,240,245,.1) 44%, rgba(255,247,241,.82) 100%),
        radial-gradient(ellipse at 74% 38%, rgba(255,255,255,.48), transparent 34%);
    }
    .hero-tag, .ai-tag {
      position: absolute;
      top: 12px;
      z-index: 2;
      padding: 7px 10px;
      border-radius: 999px;
      background: rgba(255,255,255,.46);
      border: 1px solid rgba(255,255,255,.68);
      backdrop-filter: blur(16px);
      font-size: 11px;
      color: #79646d;
    }
    .hero-tag { right: 12px; display: inline-flex; align-items: center; gap: 6px; }
    .hero-tag::before { content: ""; width: 6px; height: 6px; border-radius: 999px; background: #d88f92; box-shadow: 0 0 0 4px rgba(216,143,146,.12); }
    .ai-tag { display: none; }
    .hero-caption {
      position: absolute;
      z-index: 2;
      left: 18px;
      right: 18px;
      bottom: 14px;
      text-align: center;
      color: #6b555b;
      font-size: 13px;
      line-height: 1.75;
    }
    .title {
      margin: 18px 2px 0;
      text-align: center;
      font-size: 30px;
      line-height: 1.36;
      letter-spacing: .04em;
      font-weight: 600;
      color: #7f3e3d;
      text-shadow: 0 1px 0 rgba(255,255,255,.6);
    }
    .title .em {
      color: #bd6b6a;
      background: linear-gradient(180deg, transparent 58%, rgba(255,206,211,.68) 0);
    }
    .subtitle {
      margin: 13px auto 0;
      max-width: 320px;
      text-align: center;
      font-size: 14px;
      line-height: 1.9;
      color: var(--muted);
    }

    .home-entry {
      margin: 15px 2px 0;
      padding: 13px;
      border-radius: 24px;
      background: rgba(255,255,255,.40);
      border: 1px solid rgba(255,255,255,.68);
      box-shadow: 0 12px 34px rgba(142,98,123,.10);
      backdrop-filter: blur(14px);
    }
    .home-entry-title {
      text-align: center;
      color: #7b6269;
      font-size: 13px;
      line-height: 1.65;
      margin-bottom: 10px;
    }
    .home-choices {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 8px;
    }
    .home-choice {
      min-height: 58px;
      border: 1px solid rgba(255,255,255,.78);
      border-radius: 18px;
      background: linear-gradient(180deg, rgba(255,255,255,.62), rgba(255,242,244,.42));
      color: #765e66;
      font-size: 12px;
      line-height: 1.35;
      cursor: pointer;
      box-shadow: 0 10px 24px rgba(210,134,137,.10), inset 0 1px 0 rgba(255,255,255,.72);
      transition: transform .18s ease, box-shadow .18s ease, background .18s ease;
    }
    .home-choice:active { transform: scale(.985); }
    .home-choice:hover { box-shadow: 0 14px 30px rgba(210,134,137,.14), inset 0 1px 0 rgba(255,255,255,.78); }
    .home-note {
      margin-top: 10px;
      text-align: center;
      color: #9a858c;
      font-size: 11px;
      line-height: 1.6;
    }

    .btn {
      width: 100%;
      border: 0;
      border-radius: 20px;
      padding: 14px 18px;
      margin-top: 18px;
      color: white;
      font-size: 15px;
      font-weight: 600;
      letter-spacing: .03em;
      background: linear-gradient(135deg, #e78986 0%, #e9a1a6 50%, #e6c3ff 100%);
      box-shadow: 0 15px 32px rgba(215, 127, 125, .28), inset 0 1px 0 rgba(255,255,255,.44);
      cursor: pointer;
      transition: transform .18s ease, box-shadow .18s ease, opacity .18s ease;
    }
    .btn:active { transform: scale(.985); }
    .btn:disabled { opacity: .72; cursor: not-allowed; box-shadow: none; }
    .ghost-row { display: flex; justify-content: space-between; gap: 10px; margin-top: 12px; }
    .ghost {
      border: 1px solid rgba(255,255,255,.7);
      background: rgba(255,255,255,.4);
      color: #8a737b;
      border-radius: 15px;
      padding: 10px 12px;
      font-size: 12px;
      backdrop-filter: blur(10px);
      cursor: pointer;
    }
    .section-title {
      text-align: center;
      margin: 8px auto 6px;
      color: #7d4545;
      font-size: 25px;
      line-height: 1.42;
      font-weight: 600;
      letter-spacing: .04em;
    }
    .section-title .red { color: #cf7777; }
    .section-sub {
      text-align: center;
      font-size: 13px;
      line-height: 1.8;
      color: #8a7880;
      margin: 0 auto 14px;
      max-width: 310px;
    }
    .bubble-area {
      position: relative;
      height: 490px;
      border-radius: 30px;
      background:
        radial-gradient(circle at 18% 18%, rgba(255,255,255,.86), transparent 20%),
        radial-gradient(circle at 82% 24%, rgba(255,226,234,.58), transparent 28%),
        radial-gradient(circle at 56% 78%, rgba(255,241,182,.34), transparent 30%),
        linear-gradient(180deg, rgba(255,255,255,.34), rgba(255,247,244,.20));
      border: 1px solid rgba(255,255,255,.66);
      overflow: hidden;
      box-shadow: inset 0 1px 0 rgba(255,255,255,.60), 0 18px 54px rgba(196, 124, 134, .08);
    }
    .bubble-area::before,
    .bubble-area::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      pointer-events: none;
      filter: blur(2px);
    }
    .bubble-area::before {
      width: 180px;
      height: 180px;
      left: -48px;
      top: 90px;
      background: radial-gradient(circle, rgba(255,219,225,.42), transparent 66%);
    }
    .bubble-area::after {
      width: 210px;
      height: 210px;
      right: -70px;
      bottom: -36px;
      background: radial-gradient(circle, rgba(232,213,255,.34), transparent 67%);
    }
    .anxiety {
      --rot: 0deg;
      position: absolute;
      border: 1px solid rgba(255,255,255,.78);
      min-height: 68px;
      padding: 14px 16px 13px;
      background: linear-gradient(135deg, rgba(255,255,255,.72), rgba(255,230,236,.42));
      box-shadow: 0 15px 38px rgba(179, 116, 126, .13), inset 0 1px 0 rgba(255,255,255,.66);
      color: #6a565e;
      font-size: 13.8px;
      line-height: 1.45;
      cursor: pointer;
      text-align: left;
      animation: floaty 5.2s ease-in-out infinite;
      transition: transform .22s ease, box-shadow .22s ease, background .22s ease, border-color .22s ease;
      transform: rotate(var(--rot));
      backdrop-filter: blur(16px);
    }
    .anxiety span { display: block; position: relative; z-index: 2; }
    .anxiety::before {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: inherit;
      background: radial-gradient(circle at 24% 16%, rgba(255,255,255,.62), transparent 35%);
      pointer-events: none;
    }
    .anxiety::after {
      content: "✦";
      position: absolute;
      right: 14px;
      top: 12px;
      color: rgba(209, 132, 132, .0);
      font-size: 13px;
      transform: scale(.8);
      transition: opacity .22s ease, color .22s ease, transform .22s ease;
    }
    .anxiety:active, .anxiety.selected {
      transform: rotate(var(--rot)) scale(1.045);
      background: linear-gradient(135deg, rgba(255,244,246,.96), rgba(255,255,255,.76));
      border-color: rgba(237, 162, 162, .86);
      box-shadow: 0 20px 48px rgba(215, 127, 125, .24), 0 0 0 6px rgba(255,214,219,.28), inset 0 1px 0 rgba(255,255,255,.75);
    }
    .anxiety.selected::after {
      color: rgba(209, 132, 132, .82);
      transform: scale(1);
    }
    .anxiety small {
      position: relative;
      z-index: 2;
      display: inline-flex;
      align-items: center;
      margin-bottom: 5px;
      padding: 3px 8px;
      border-radius: 999px;
      color: #cf7777;
      font-size: 10px;
      line-height: 1;
      background: rgba(255,225,226,.56);
    }
    .anxiety.shape-cloud { border-radius: 38px 58px 46px 54px; }
    .anxiety.shape-note { border-radius: 22px 34px 26px 30px; background: linear-gradient(135deg, rgba(255,250,245,.76), rgba(255,225,233,.44)); }
    .anxiety.shape-tag { border-radius: 34px 22px 34px 22px; background: linear-gradient(135deg, rgba(255,255,255,.72), rgba(255,236,216,.45)); }
    .anxiety.shape-bubble { border-radius: 999px; background: linear-gradient(135deg, rgba(255,238,240,.74), rgba(255,255,255,.52)); }
    .anxiety.shape-paper { border-radius: 26px; background: linear-gradient(145deg, rgba(255,255,255,.78), rgba(246,235,255,.36)); }
    .anxiety-cta-row {
      display: grid;
      grid-template-columns: 1fr;
      margin-top: 12px;
    }
    .anxiety-cta-row .btn {
      min-height: 48px;
      font-size: 15px;
      box-shadow: 0 14px 28px rgba(220,122,104,.17);
    }
    .anxiety-cta-row .btn:disabled {
      opacity: .48;
      cursor: default;
      filter: grayscale(.18);
      box-shadow: none;
    }
    @keyframes floaty {
      0%, 100% { translate: 0 0; }
      50% { translate: 0 -8px; }
    }
    .tip {
      margin-top: 10px;
      text-align: center;
      color: #9a858c;
      font-size: 11.5px;
    }
    .scratch {
      position: relative;
      min-height: 420px;
      border-radius: 30px;
      padding: 18px;
      overflow: hidden;
      background:
        radial-gradient(circle at 82% 18%, rgba(255,241,182,.65), transparent 25%),
        radial-gradient(circle at 15% 80%, rgba(255,226,234,.66), transparent 30%),
        linear-gradient(145deg, rgba(255,255,255,.72), rgba(255,245,230,.52));
      border: 1px solid rgba(255,255,255,.72);
      box-shadow: 0 18px 48px rgba(153, 103, 123, .15);
    }
    .paper {
      position: relative;
      margin: 34px auto 0;
      width: 91%;
      min-height: 235px;
      border-radius: 26px;
      background:
        linear-gradient(135deg, rgba(255,255,255,.88), rgba(255,241,230,.78)),
        radial-gradient(circle at 80% 20%, rgba(255,226,234,.7), transparent 24%);
      border: 1px solid rgba(255,255,255,.85);
      box-shadow: 0 16px 35px rgba(130, 98, 107, .14);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      text-align: center;
      overflow: hidden;
    }
    .paper::before {
      content: "";
      position: absolute;
      inset: 22px;
      border-radius: 18px;
      border: 1px dashed rgba(214, 139, 142, .22);
    }
    .heal-line {
      position: relative;
      z-index: 2;
      font-size: 19px;
      line-height: 1.95;
      color: #6b555b;
      letter-spacing: .06em;
    }
    .mask {
      position: absolute;
      inset: 0;
      z-index: 4;
      border: 0;
      background:
        repeating-linear-gradient(18deg, rgba(255,255,255,.26) 0 2px, transparent 2px 7px),
        radial-gradient(circle at 18% 22%, rgba(255,255,255,.8) 0 1.2px, transparent 1.4px),
        radial-gradient(circle at 78% 42%, rgba(255,255,255,.7) 0 1px, transparent 1.3px),
        linear-gradient(135deg, rgba(226,224,226,.96), rgba(255,232,237,.92), rgba(255,255,255,.94));
      color: #7a686e;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-direction: column;
      cursor: pointer;
      transition: opacity .45s ease, transform .45s ease;
      overflow: hidden;
    }
    .mask::before {
      content: "";
      position: absolute;
      inset: -35%;
      background: linear-gradient(115deg, transparent 42%, rgba(255,255,255,.68) 49%, transparent 56%);
      transform: translateX(-38%) rotate(5deg);
      opacity: .8;
      animation: pearlSweep 2.4s ease-in-out infinite;
    }
    .mask::after {
      content: "";
      position: absolute;
      inset: 14px;
      border-radius: 18px;
      border: 1px dashed rgba(255,255,255,.72);
      box-shadow: inset 0 0 28px rgba(255,255,255,.36);
    }
    @keyframes pearlSweep {
      0%, 100% { transform: translateX(-42%) rotate(5deg); opacity: .25; }
      50% { transform: translateX(36%) rotate(5deg); opacity: .9; }
    }
    .mask.open {
      pointer-events: none;
      animation: scratchReveal .92s cubic-bezier(.2,.8,.2,1) forwards;
    }
    @keyframes scratchReveal {
      0% { opacity: 1; clip-path: polygon(0 0,100% 0,100% 100%,0 100%); }
      22% { clip-path: polygon(0 0,100% 0,100% 100%,0 100%,0 62%,42% 50%,0 38%); }
      52% { clip-path: polygon(0 0,100% 0,100% 100%,0 100%,0 76%,74% 54%,0 30%); }
      78% { opacity: .75; clip-path: polygon(0 0,100% 0,100% 100%,0 100%,0 92%,100% 62%,100% 38%,0 12%); }
      100% { opacity: 0; transform: scale(1.025); clip-path: polygon(0 0,100% 0,100% 0,0 0); }
    }
    .mask b { position: relative; z-index: 3; font-size: 18px; }
    .mask .mask-sub { position: relative; z-index: 3; margin-top: 8px; font-size: 12px; color: #9a858c; }
    .scratch-streak {
      position: absolute;
      z-index: 5;
      height: 12px;
      border-radius: 999px;
      background: rgba(255,255,255,.86);
      box-shadow: 0 0 16px rgba(255,255,255,.8), 0 0 0 1px rgba(255,255,255,.45);
      opacity: 0;
      transform: rotate(-13deg) scaleX(.2);
      transform-origin: left center;
    }
    .mask.open .scratch-streak { animation: scratchLine .72s ease-out both; }
    .scratch-streak.s1 { width: 58%; left: 16%; top: 30%; animation-delay: .04s; }
    .scratch-streak.s2 { width: 68%; left: 10%; top: 44%; animation-delay: .13s; }
    .scratch-streak.s3 { width: 56%; left: 25%; top: 58%; animation-delay: .23s; }
    .scratch-streak.s4 { width: 46%; left: 18%; top: 70%; animation-delay: .34s; }
    @keyframes scratchLine {
      0% { opacity: 0; transform: rotate(-13deg) scaleX(.1); }
      25% { opacity: 1; }
      100% { opacity: 0; transform: rotate(-13deg) scaleX(1); }
    }

    .scratch-layer {
      position: absolute;
      inset: 0;
      z-index: 4;
      border-radius: 22px;
      overflow: hidden;
      touch-action: none;
      user-select: none;
    }
    .scratch-layer::before {
      content: "";
      position: absolute;
      z-index: 6;
      inset: -35%;
      background: linear-gradient(115deg, transparent 42%, rgba(255,255,255,.62) 49%, transparent 56%);
      transform: translateX(-38%) rotate(5deg);
      opacity: .72;
      pointer-events: none;
      animation: pearlSweep 2.4s ease-in-out infinite;
      transition: opacity .35s ease;
    }
    .scratch-layer.done::before { opacity: 0; }
    .scratch-layer.started .scratch-hint { opacity: 0; transform: translateY(-8px); }
    .scratch-canvas {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      z-index: 4;
      border-radius: 22px;
      cursor: grab;
      touch-action: none;
      transition: opacity .5s ease, transform .5s ease;
    }
    .scratch-canvas:active { cursor: grabbing; }
    .scratch-canvas.open {
      opacity: 0;
      transform: scale(1.018);
      pointer-events: none;
    }
    .scratch-hint {
