    /* ===== 夜空湖面版和解卡背景：用于最终弹窗与保存图片 ===== */
    .final {
      background:
        radial-gradient(circle at 50% 12%, rgba(183, 196, 255, .20), transparent 34%),
        rgba(16, 20, 52, .56) !important;
      backdrop-filter: blur(14px) saturate(1.05) !important;
      -webkit-backdrop-filter: blur(14px) saturate(1.05) !important;
    }

    .final-card {
      position: relative !important;
      overflow: hidden !important;
      isolation: isolate !important;
      background-image:
        linear-gradient(180deg, rgba(252, 250, 255, .58) 0%, rgba(244, 245, 255, .42) 42%, rgba(255, 251, 246, .58) 100%),
        url("data:image/png;base64,") !important;
      background-size: cover !important;
      background-position: center center !important;
      border-color: rgba(255,255,255,.72) !important;
      box-shadow: 0 34px 96px rgba(11, 17, 50, .38) !important;
    }

    .final-card::before {
      content: "";
      position: absolute;
      inset: 0;
      z-index: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 48% 14%, rgba(255,255,255,.42), transparent 32%),
        linear-gradient(180deg, rgba(255,255,255,.28), rgba(255,255,255,.12) 44%, rgba(17,26,66,.13));
    }

    .final-card > * {
      position: relative;
      z-index: 1;
    }

    .close {
      z-index: 20 !important;
      pointer-events: auto !important;
      background: rgba(255,255,255,.50) !important;
      border-color: rgba(255,255,255,.72) !important;
      color: #5e5874 !important;
      box-shadow: 0 10px 28px rgba(19, 28, 68, .16) !important;
    }

    .close:active {
      transform: scale(.96);
    }

    .final-title {
      color: #514567 !important;
      text-shadow: 0 1px 10px rgba(255,255,255,.50);
    }

    .final-section {
      background: linear-gradient(135deg, rgba(255,255,255,.74), rgba(249,247,255,.58)) !important;
      border-color: rgba(255,255,255,.78) !important;
      box-shadow: 0 10px 30px rgba(26, 31, 74, .10), inset 0 1px 0 rgba(255,255,255,.46);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
    }

    .final-section label {
      color: #7f6c9d !important;
      font-weight: 600;
    }

    .final-section div {
      color: #4f465a !important;
    }

    .footer-note {
      color: #6e6577 !important;
      text-shadow: 0 1px 8px rgba(255,255,255,.50);
    }

    .save-actions .btn {
      box-shadow: 0 16px 34px rgba(25, 33, 84, .17) !important;
    }

